using System;using System.IO;using System.Reflection;using System.Runtime.Serialization;using System.Collections.Generic;using System.Linq;using ElementalHearts;using RimWorld;using Verse;using Verse.AI;using UnityEngine;
class CelestialRegression {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static T Empty<T>(){return (T)FormatterServices.GetUninitializedObject(typeof(T));}
 static void Set(object o,string n,object v){o.GetType().GetField(n,F).SetValue(o,v);}
 static object Get(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}
 static void Check(bool ok,string s){if(!ok)throw new Exception(s);}
 static int Main(string[] args){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string n=new AssemblyName(e.Name).Name;string p=n=="ElementalHearts"?args[1]:n=="0Harmony"?args[2]:Path.Combine(args[0],n+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};try{typeof(CelestialRegression).GetMethod("Run",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 static void Run(){
  Check(CelestialRules.MaxVictims==16&&CelestialRules.MaxSearchThings==512&&CelestialRules.MaxCandidates==32,"local combat budgets");
  for(int tick=-20;tick<1000;tick++)for(int s=0;s<20;s++){int f=CelestialVisualAssets.FrameIndex(s,tick,60);Check(f>=0&&f<CelestialVisualAssets.Count(s),"frame bounds");float p=CelestialRules.Progress(tick,12);Check(p>=0&&p<=1&&!float.IsNaN(p),"dash curve");}
  for(int mask=0;mask<32;mask++){bool[] valid=Enumerable.Range(0,5).Select(i=>(mask&(1<<i))!=0).ToArray();int chosen=CelestialRules.Choose(0,3,2,valid);Check(chosen<0?mask==0:valid[chosen],"combo selects unavailable skill");if(valid[4])Check(chosen==4,"surrounded trigger priority");else if(valid[3])Check(chosen==3,"Radiance finisher priority");}
  Check(CelestialRules.DashDuration(0)==5&&CelestialRules.DashDuration(100)==12,"unbounded movement animation");
  var fx=new MapComponent_CelestialVfx(null);int last=0;for(int i=0;i<10000;i++)last=fx.Add(CelestialEffect.CoronaSpin,Vector3.zero,Vector3.one,0,99999,999,999);var slots=(Array)Get(fx,"effects");Check(slots.Length==128&&((Array)Get(fx,"echoes")).Length==32&&((Array)Get(fx,"adornments")).Length==128,"effect pool sizes");foreach(var e in slots){Check((int)Get(e,"duration")<=300&&(float)Get(e,"width")<=16&&(float)Get(e,"height")<=32,"unbounded effect duration/size");}fx.Stop(last);fx.Stop(last);Check(fx.Add(CelestialEffect.DawnCrescent,new Vector3(float.NaN,0,0),Vector3.zero,0,10,1,1)==0&&fx.Add(CelestialEffect.DawnCrescent,Vector3.zero,Vector3.zero,0,10,1,1,null,10)==0,"invalid/expired effects accepted");
  var p1=Empty<Pawn>();p1.jobs=Empty<Pawn_JobTracker>();p1.jobs.curJob=new Job{def=new JobDef{defName=CelestialAscendant.Technique}};Check(CelestialAscendant.Busy(p1),"owned technique gate");p1.jobs.curJob.def.defName="Goto";Check(!CelestialAscendant.Busy(p1),"replaced order retains gate");
  var cast=new JobDriver_CelestialTechnique{pawn=Empty<Pawn>(),job=new Job{count=5}};Set(cast,"elapsed",17);Set(cast,"committed",true);Set(cast,"initialized",true);Set(cast,"struck",new HashSet<int>{71,72});var state=new CelestialSaveCase{cast=cast,comp=new HediffComp_CelestialAbilities{autoCombat=false,nonLethal=true,readyAt=new List<int>{11,22,33,44,55,66},mirageArmedUntil=600}};string file=Path.Combine(Path.GetTempPath(),"Celestial_"+Guid.NewGuid().ToString("N")+".xml");Scribe.saver.InitSaving(file,"CelestialTest");Scribe_Deep.Look(ref state,"state");Scribe.saver.FinalizeSaving();var xml=new System.Xml.XmlDocument();xml.Load(file);Check(xml.SelectSingleNode("CelestialTest/state/cast/EH_celestialElapsed").InnerText=="17"&&xml.SelectSingleNode("CelestialTest/state/cast/EH_celestialCommitted").InnerText=="True"&&xml.SelectNodes("CelestialTest/state/cast/EH_celestialVictims/li").Count==2,"saved impact commitment/victim dedup");Check(xml.SelectSingleNode("CelestialTest/state/EH_celestialAuto").InnerText=="False"&&xml.SelectSingleNode("CelestialTest/state/EH_celestialNonLethal").InnerText=="True"&&xml.SelectNodes("CelestialTest/state/EH_celestialReadyAt/li").Count==6,"saved controls/cooldowns");File.Delete(file);
  Console.WriteLine("PASS: finite combat/frame/dash/selection rules, 10,000 emissions retain fixed pools and bounded lifetime/size, invalid input rejection, interruption gate release and native saved stage/impact/victims/modes/cooldowns.");
 }
}
public class CelestialSaveCase:IExposable {public JobDriver_CelestialTechnique cast;public HediffComp_CelestialAbilities comp;public void ExposeData(){Scribe_Deep.Look(ref cast,"cast");comp.CompExposeData();}}
